(function(root){'use strict';const ui=root.DuelUITranslations;const names={"blackwing-2009":["Blackwing Gale · 2009","BF・疾風 · 2009"],"cat-gladiator-2009":["Cat Gladiator Beast · 2009","猫剣闘獣 · 2009"],"cat-synchro-2009":["Cat Synchro · 2009","猫シンクロ · 2009"],"frog-ftk-2010":["Frog Cannon · 2010","ガエル・キャノン · 2010"],"blackwing-2010":["Blackwing Whirlwind · 2010","BF・旋風 · 2010"],"herald-2010":["Herald of Perfection · 2010","神光の宣告者 · 2010"],"agents-2011":["Agent Fairy · 2011","代行天使 · 2011"],"junk-doppel-2011":["Junk Doppel · 2011","ジャンクドッペル · 2011"],"six-samurai-2011":["Legendary Six Samurai · 2011","真六武衆 · 2011"],"inzektor-2012":["Inzektor · 2012","甲虫装機 · 2012"],"wind-up-2012":["Wind-Up · 2012","ゼンマイ · 2012"],"mermail-atlantean-2012":["Mermail Atlantean · 2012","水精鱗海皇 · 2012"],"dragon-ruler-2013":["Dragon Ruler Inferno · 2013","征竜・烈火 · 2013"],"spellbook-2013":["Spellbook Judgment · 2013","魔導書・神判 · 2013"],"evilswarm-2013":["Evilswarm Pandemic · 2013","ヴェルズ・疫病 · 2013"],"fire-fist-2013":["Fire Fist Four-Axis · 2013","炎星・四軸 · 2013"],"bujin-2013":["Bujin Descent · 2013","武神降臨 · 2013"],"shaddoll-2014":["Shaddoll Weave · 2014","影依の織り手 · 2014"],"qliphort-2014":["Qliphort Reboot · 2014","クリフォート再起動 · 2014"],"nekroz-2014":["Nekroz Ascension · 2014","影霊衣降臨 · 2014"],"tellarknight-2015":["World Champion · Tellarknight · 2015","世界王者 · テラナイト · 2015"],"nekroz-2015":["World Runner-up · Nekroz · 2015","世界準優勝 · 影霊衣 · 2015"],"performapal-performage-2015":["Year-end Favorites · Performapal Performage · 2015","年間人気 · EMEm · 2015"],"blue-eyes-2016":["World Champion · Blue-Eyes · 2016","世界王者 · 青眼 · 2016"],"majespecter-2016":["World Bronze · Majespecter · 2016","世界3位 · マジェスペクター · 2016"],"zoodiac-2016":["Year-End Winner · Zoodiac · 2016","年末優勝 · 十二獣 · 2016"],"dinosaur-2017":["World Champion · True King Dinosaur · 2017","世界王者 · 真竜皇竜星恐竜 · 2017"],"true-draco-2017":["World Bronze · True Draco · 2017","世界3位 · 真竜 · 2017"],"zoodiac-2017":["Tournament Winner · Zoodiac · 2017","大会優勝 · 十二獣 · 2017"],"trickstar-2017":["Yearly Favorites · Trickstar · 2017","年間人気 · トリックスター · 2017"],"spyral-2017":["Year-End Winner · SPYRAL · 2017","年末優勝 · SPYRAL · 2017"],"trickstar-2018":["World Champion · Trickstar · 2018","世界王者・トリックスター · 2018"],"altergeist-2018":["World Runner-up · Altergeist · 2018","世界準優勝・オルターガイスト · 2018"],"gouki-2018":["World Third Place · Gouki · 2018","世界3位・剛鬼 · 2018"],"sky-striker-2018":["World Fourth Place · Sky Striker · 2018","世界4位・閃刀姫 · 2018"],"thunder-dragon-2018":["Annual Favorite · Thunder Dragon · 2018","年間人気・サンダー・ドラゴン · 2018"],"salamangreat-2019":["World Champion · Salamangreat · 2019","世界王者・サラマングレイト · 2019"],"orcust-2019":["Annual Favorite · Orcust · 2019","年間人気・オルフェゴール · 2019"],"dragon-link-2019":["Annual Favorite · Dragon Link · 2019","年間人気・ドラゴンリンク · 2019"],"sky-striker-2019":["Annual Favorite · Sky Striker · 2019","年間人気・閃刀姫 · 2019"],"endymion-2019":["Annual Favorite · Endymion · 2019","年間人気・エンディミオン · 2019"],"eldlich-2020":["Annual Metagame · Eldlich · 2020","年間環境・エルドリッチ · 2020"],"dogmatika-invoked-2020":["Annual Metagame · Dogmatika Invoked · 2020","年間環境・ドラグマ召喚獣 · 2020"],"virtual-world-2020":["Annual Metagame · Virtual World · 2020","年間環境・電脳堺 · 2020"],"adamancipator-2020":["Annual Metagame · Adamancipator · 2020","年間環境・アダマシア · 2020"],"zoodiac-2020":["Annual Metagame · Zoodiac ZEUS · 2020","年間環境・十二獣アーゼウス · 2020"]},descriptions={"blackwing-2009":["Black Whirlwind searches, Kalut protects battles, and Blizzard enables Synchro plays. Inspired by the 2009 world champion.","黒い旋風でサーチし、カルートで戦闘を支援。ブリザードからシンクロへ。2009年世界王者の戦術を参考にした構築。"],"cat-gladiator-2009":["Rescue Cat supports Gladiator Beast tag-outs and Contact Fusion. Inspired by the 2009 runner-up.","レスキューキャットから剣闘獣を展開し、戦闘後の交代とコンタクト融合へ。2009年世界準優勝の戦術が基礎。"],"cat-synchro-2009":["A popular 2009 alternative: Summoner Monk, Rescue Cat and Flamvell build flexible Synchro combinations.","2009年に活躍した猫シンクロ。サモンプリースト、レスキューキャット、フレムベルでレベルを組み合わせる。"],"frog-ftk-2010":["Inspired by the 2010 champion: Swap Frog, Substitoad and Ronintoadin recycle resources into Mass Driver damage.","2010年世界王者のガエルを参考に、鬼ガエル、イレカエル、粋カエルをマスドライバーのダメージへつなぐ。"],"blackwing-2010":["The 2010 Blackwing engine adds Zephyros and resource Spells. Draw cards before committing to a Summon route.","2010年のBFにゼピュロスやドロー魔法を採用。特殊召喚を制限する魔法の使用順に注意。"],"herald-2010":["Inspired by the 2010 third-place strategy: exact Ritual Levels and Fairy cards in hand support Herald negation.","2010年世界3位の宣告者を参考にした構築。儀式のレベル合計と手札の天使族で神光の宣告者を支える。"],"agents-2011":["Inspired by the 2011 champion: Earth searches, Venus summons Shine Balls, and Hyperion converts the Graveyard into removal.","2011年世界王者の代行天使。アースでサーチ、ヴィーナスで球体を展開し、ヒュペリオンで墓地を除去に使う。"],"junk-doppel-2011":["Junk Doppel links Tokens and Plant Tuners into Formula Synchron, Hyper Librarian and Shooting Quasar Dragon.","ジャンクドッペル。トークンと植物チューナーからフォーミュラ、ライブラリアン、シューティング・クェーサーへ。"],"six-samurai-2011":["A popular 2011 alternative: Kageki and Kagemusha summon Shi En, while Dojo and United replenish resources.","2011年の代表的な真六武衆。カゲキと影武者からシエンへ。道場と結束で展開を継続。"],"inzektor-2012":["Inspired by the Inzektor-heavy 2012 Worlds: Hornet leaving its host triggers Dragonfly or Centipede; Ladybug changes Levels.","甲虫装機が上位を占めた2012年世界大会が基礎。ホーネットの装備解除からダンセルとセンチピードを展開。"],"wind-up-2012":["A varied 2012 alternative: Shark adjusts Levels, Magician and Rat extend plays, and Zenmaity connects Rank 3 monsters.","2012年を代表するゼンマイ。シャークのレベル調整とマジシャン、ネズミの展開でランク3につなぐ。"],"mermail-atlantean-2012":["A late-2012 WATER strategy. Discard Atlanteans as WATER monster costs, and use Abyss-sphere and Linde to extend plays.","2012年後半の水精鱗海皇。水属性の効果コストで海皇を墓地へ送り、アビスフィアーとリンデで展開を継続。"],"dragon-ruler-2013":["Inspired by 2013 world champion Shin En Huang. Each Dragon Ruler discards itself together with a same-Attribute Dragon to search or revive, then overlays into Number 11: Big Eye and Mecha Phantom Beast Dracossack while Super Rejuvenation turns the hand into advantage.","2013年世界王者Shin En Huangの征竜を参考にした構築。四色の征竜は自身と同属性のドラゴンを捨ててサーチと蘇生を行い、No.11 ビッグ・アイと幻獣機ドラゴサックへ繋ぐ。超再生で手札を循環させる。"],"spellbook-2013":["Inspired by 2013 runner-up David J. Keener III. Spellbook of Judgment stacks same-name Spells and searches Prophecy monsters, while High Priestess of Prophecy and The Grand Spellbook Tower recycle everything back into the hand.","2013年世界準優勝David J. Keener IIIの魔導書を参考にした構築。魔導書の神判で同名魔法を積み魔導をサーチし、魔導法士ジュノンと魔導書院ラメイソンで資源を回収する。"],"evilswarm-2013":["Third most successful 2013 OCG archetype and the most stable non-Dragon-Ruler, non-Spellbook system; chosen by the popularity rule because the championship podium was homogeneous. Rescue Rabbit assembles the Level 4 Evilswarm, and Evilswarm Ophion locks high-Level Special Summons out of the game.","2013年OCGで上位3番目、征竜と魔導書以外では最も安定した入魔。表彰台が同質化したため人気基準で選出。レスキューラビットでヴェルズを並べ、ヴェルズ・オピオンで高レベル特殊召喚を封じる。"],"fire-fist-2013":["A 2013 OCG build of Four-Axis Fire Fist, ranked 4th in both of the year’s metagame reports. Tenki searches the Beast-Warriors, Tensu grants the extra Normal Summon, and Tiger King Sets a Fire Formation on arrival and negates opposing face-up Effect Monsters each turn.","2013年のOCG上位で第4位だった4軸炎星。天璣で獣戦士をサーチし、天枢で通常召喚を追加。タイガー・キングはエクシーズ召喚時に炎舞をセットし、毎ターン相手の表側効果モンスターを無効化する。"],"bujin-2013":["A representative build of Bujin, the 2013 debut archetype. The Bujingi pay for themselves from the hand or Graveyard and rewrite combat: Crane doubles a Bujin’s original ATK, Turtle banishes itself to stop a targeting effect. Yamato searches another Bujin each End Phase.","2013年に登場した武神の代表的な構築。武神器は手札や墓地から自身を消費して戦闘結果を書き換える。ヤマトは毎ターンのエンドフェイズに武神をサーチし、4軸でスサノオとカグツチを重ねる。"],"shaddoll-2014":["An adaptation of the third most represented strategy in the 2014 year-end OCG report. Fusion materials trigger graveyard effects.","2014年末OCG上位分布3位のシャドールを参考にした構築。融合素材の墓地効果で展開する。"],"qliphort-2014":["An adaptation of the second most represented strategy in the 2014 year-end OCG report. Scout searches, Pendulum Summons supply Tributes.","2014年末OCG上位分布2位のクリフォートを参考にした構築。ツールでサーチし、ペンデュラム召喚からアドバンス召喚へ。"],"nekroz-2014":["An adaptation of the most represented strategy in the 2014 year-end OCG report. Ritual searches and Kaleidoscope turn the Extra Deck into resources.","2014年末OCG上位分布1位の影霊衣を参考にした構築。儀式サーチと万華鏡によるエクストラデッキ活用。"],"tellarknight-2015":["Hiyama Shunsuke’s 2015 Worlds winning 41-card list. Deneb, Vega and Altair build Triverr; Ptolemaeus offers Rank-Up control. The source file preserves the side deck.","2015年世界王者・桧山俊介のメイン41枚を再現。デネブ、ベガ、アルタイルからトライヴェールへ。プトレマイオスでランクアップ。サイドは出典データに保存。"],"nekroz-2015":["Galileo De Obaldia’s 41-card 2015 Worlds runner-up list. Ritual searches and Kaleidoscope unlock Trishula; Hands, Ghost Ogre and Royal Decree support the engine.","2015年世界準優勝Galileo De Obaldiaのメイン41枚。儀式サーチと万華鏡からトリシューラへ。ハンド、幽鬼うさぎ、王宮のお触れで支援。"],"performapal-performage-2015":["A representative late-2015 OCG Performapal Performage build. Joker and Monkeyboard find scales; Luster destroys Plushfire to recruit Performages and build Synchro/Xyz boards.","2015年末OCGの代表的なEMEm。ジョーカーとモンキーボードでスケールを揃え、ラスターPでヒグルミを破壊して展開。シンクロとランク4を使い分ける。"],"blue-eyes-2016":["Hiyama Shunsuke’s 42-card 2016 Worlds champion list. Sage and Ancients develop Spirit Dragon, Azure-Eyes and Return of the Dragon Lords; Crystal Wing and Hope Harbinger provide disruption. The original side deck is preserved in the source file.","2016年世界王者・桧山俊介のメイン42枚。賢士と太古の白石から精霊龍・蒼眼の銀龍へ。復活の福音で継続し、クリスタルウィングとタイタニック・ギャラクシーで妨害。サイドは出典ファイルに保存。"],"majespecter-2016":["Kajihara Soichiro’s 41-card third-place Worlds list. Majespecters search backrow, Kirin controls the field, and Dracoslayer and Speedroid engines offer Pendulum, Synchro and Xyz routes.","2016年世界3位・梶原宗一郎のメイン41枚。マジェスペクターのサーチとユニコーンのバウンスに、竜剣士とSRのシンクロ・エクシーズ展開を組み合わせる。"],"zoodiac-2016":["Mihara’s 41-card winning list from the 7th Tsudanuma CS, published in the OCG 2016.10 review. Ratpier, Broadbull and Drident demonstrate Zoodiac overlay routes. Selected for variety because both Worlds finalists used Blue-Eyes.","OCG 2016.10総括掲載、第7回津田沼CS優勝・みはらのメイン41枚。モルモラット、ブルホーン、ドランシアで十二獣の重ねるエクシーズを体験。世界大会決勝の青眼重複を避ける代表枠。"],"dinosaur-2017":["Tsujimura Ryosuke’s original 2017 Worlds champion list, 40 main / 15 extra / 15 side. Destroy baby Dinosaurs to develop Denglong, Synchros and Ultimate Conductor Tyranno.","2017年世界王者・辻村涼介の原表、メイン40／EX15／サイド15。恐竜の効果破壊から源竜星とシンクロを展開し、究極伝導恐獣で攻める。"],"true-draco-2017":["Marcello Barberi’s original third-place 2017 Worlds list, 40/15/15. Tribute Continuous Spells and Traps, trigger their graveyard removal, and grant Master Peace immunity from the tributed card types.","2017年世界3位・Marcello Barberiの原表、40/15/15。永続魔法・罠をリリースし、墓地効果で除去。真竜剣皇はリリースしたカードの種類への耐性を得る。"],"zoodiac-2017":["Kira’s winning Hatti CS x Oarashi Cup in Kitakyushu list, 40/15/15. Chakanine revives Zoodiacs; Drident, Ash Blossom and Ghost Ogre control the mirror match.","北九州はっちCS×大嵐杯優勝・キラの原表、40/15/15。ライカで蘇生し、ドランシア・うらら・うさぎで相手を妨害。"],"trickstar-2017":["An authored 40/15/15 representative build based on the documented 2017 Trickstar metagame, not an attributed tournament list. Candina searches, Lycoris punishes added cards, and Reincarnation with Droll disrupts the hand.","2017年の入賞記録を参考に作成した代表構築、40/15/15。選手の原表ではない。キャンディナでサーチし、マンジュシカとリンカーネイション、ドロールで手札を牽制。"],"spyral-2017":["Calvin Ang’s winning Singapore Winter Asia qualifier list published in late 2017, 42/15/15. Drone arranges the opponent’s deck, Double Helix develops SPYRAL, and Grinder Golem enables Link routes.","2017年末掲載、冬季アジア大会シンガポール予選優勝・Calvin Angの原表、42/15/15。ドローンとダブルヘリックスで展開し、トーチ・ゴーレムからリンクへ。"],"trickstar-2018":["Wang Chia-Ching’s original Worlds champion list: Trickstar searches and burn, Eater of Millions and Scapegoat Link plays. Full 42/15/15.","王家慶選手の世界優勝リスト。トリックスターのサーチとバーン、百万喰らい、スケープ・ゴートからのリンク。42／15／15。"],"altergeist-2018":["Bohdan Temnyk’s original Worlds runner-up list: traps trigger Multifaker, with Silquitous and Kunquery controlling the field. Full 40/15/15.","Bohdan Temnyk選手の世界準優勝リスト。罠からマルチフェイカー、シルキタスとクンティエリで盤面を制御。40／15／15。"],"gouki-2018":["Francesco Simoncelli’s original third-place Worlds list: Gouki material searches, Re-Match and Isolde extend Link plays. Firewall uses its current errata. Full 40/15/15.","Francesco Simoncelli選手の世界3位リスト。剛鬼の素材サーチ、再戦、イゾルデでリンク展開。ファイアウォールは現行テキスト。40／15／15。"],"sky-striker-2018":["Jung Seung-Chul’s original fourth-place Worlds list: empty Main Monster Zones enable Sky Striker spells; Engage, Kagari and Shizuku recycle resources. Full 40/15/15.","Jung Seung-Chul選手の世界4位リスト。メインモンスターゾーンを空け、エンゲージ、カガリ、シズクで資源を循環。40／15／15。"],"thunder-dragon-2018":["A representative adaptation based on the July 2018 metagame: hand effects unlock Colossus; banishment and GY effects recycle resources for Thunder Dragon Fusion and Titan.","2018年7月環境を参考にした代表構築。手札効果から超雷龍、除外と墓地の循環から雷龍融合と雷神龍へ。大会原本ではない。"],"salamangreat-2019":["Kosaka Kouki’s original Worlds champion list. Gazelle loads the GY; reincarnated Sunlight Wolf recovers Roar. Full 41/15/15.","小坂光輝選手の世界優勝リスト。ガゼルで墓地を整え、転生リンクのサンライトウルフでロアーを回収。41／15／15。"],"orcust-2019":["A representative 2019 build: Scrap milling, Babel quick effects, Galatea recycling and Dingirsu removal.","2019年の代表構築。スクラップの墓地送り、バベルによるクイック効果、ガラテアの回収とディンギルスの除去。"],"dragon-link-2019":["A representative 2019 Dragon Link build. Tracer, Seyfert and Guardragons use actual Link zones to build Savage Dragon interaction.","2019年ドラゴンリンクの代表構築。トレーサー、セイファート、守護竜が実際のリンク先を使い、サベージの妨害へつなぐ。"],"sky-striker-2019":["A representative 2019 Sky Striker list with Roze and Zeke. Empty Main Monster Zones enable spells; Mystic Mine and hand traps buy time for resource loops.","ロゼとジークを加えた2019年の閃刀姫代表構築。メインモンスターゾーンを空け、魔鍾洞と手札誘発でリソース循環を支える。"],"endymion-2019":["A representative 2019 Spell Counter build. Servant expands from a scale; Jackal King and Endymion spend real counters, with Selene extending the field.","2019年の魔力カウンター代表構築。サーヴァントの展開、キングジャッカルと創聖魔導王の妨害、セレーネの展開補助。"],"eldlich-2020":["Golden Lord sends threats to the GY; Golden Land traps and Eldlixirs alternate to sustain control and finish with large monsters.","黄金卿で墓地へ送り、黄金郷罠とエルドリクシルを循環。罠で制圧し高打点で勝負を決める。"],"dogmatika-invoked-2020":["Fuse with Aleister first, then turn Extra Deck sends into Dogmatika resources. Shaddoll Schism enables Fusion plays on the opponent’s turn.","先にアレイスターで融合し、天底の使徒とドラグマでEXデッキを墓地資源へ。影依の偽典で相手ターンにも融合。"],"virtual-world-2020":["Send a different Virtual World card type to develop the field. Qinglong, Chuche and Xuanwu recycle resources into Level 3/6/9 Synchro and Xyz lines.","異なる種類の電脳堺カードを墓地へ送り展開。青龍・朱雀・玄武を循環し、レベル3・6・9のシンクロとエクシーズへ。"],"adamancipator-2020":["Excavate Rocks, rebuild with Block Dragon’s Level-8 search, and develop Dragite and Crystal Wing. A representative adaptation centered on the Rock engine.","岩石族をめくって展開し、ブロックドラゴンでレベル合計8を確保。ドラガイトとクリスタルウィングにつなぐ岩石軸の代表アレンジ。"],"zoodiac-2020":["Stack Zoodiac materials from one starter. After Boarbow battles, overlay ZEUS and convert materials into field-wide GY removal.","十二獣1枚から素材を重ね、ワイルドボウの戦闘後にアーゼウスへ。素材を全体墓地送りに変える。"]};for(const [id,labels] of Object.entries(names)){ui.deckNames[id]=labels;ui.deckDescriptions[id]=descriptions[id];const d=root.DuelData.DECKS[id];ui.messages[d.player]={en:labels[0].split(' · ')[0],ja:labels[1].split(' · ')[0]};ui.messages[d.mechanic]={en:labels[0].replace(' · ',' / '),ja:labels[1].replace(' · ',' / ')};}const chronicle=root.DuelData.families.early,lastYear=Math.max(...root.DuelData.earlyYears);ui.messages[chronicle]={en:'Card Chronicle · 1999–'+lastYear,ja:'カード年代記 · 1999–'+lastYear};})(globalThis);
